<?php declare(strict_types=1); ob_start(); $manager = (currentUser()['role'] ?? '') === 'manager'; ?>
<div class="container breadcrumb-line"><a href="/">Trang chủ</a><i class="fa-solid fa-chevron-right"></i><span>Kiểm duyệt đánh giá</span></div>
<section class="container orders-section"><div class="section-heading"><div><span class="eyebrow">KHU VỰC QUẢN TRỊ</span><h1>Kiểm duyệt đánh giá</h1><p class="muted mb-0">Đánh giá bị ẩn được giữ trong CouchDB và có thể khôi phục.</p></div></div>
<?php if (is_array($flash) && isset($flash['message'])): ?><div class="alert alert-<?= h($flash['type'] ?? 'info') ?>" role="status"><?= h($flash['message']) ?></div><?php endif; ?>
<?php if (!$manager): ?><div class="alert alert-info">Bạn có quyền xem; thao tác ẩn và khôi phục dành cho manager.</div><?php endif; ?>
<?php if ($reviews === []): ?><div class="cart-empty"><i class="fa-regular fa-comments"></i><h2>Chưa có đánh giá</h2></div><?php else: ?><div class="order-list"><?php foreach ($reviews as $review): $active = ($review['active'] ?? false) === true; $adminResponse = is_array($review['admin_response'] ?? null) ? $review['admin_response'] : null; ?><article class="order-card"><div class="order-card-heading"><div><span class="eyebrow"><?= h($review['legacy_id'] ?? $review['_id'] ?? '') ?> · SẢN PHẨM <?= h($review['product_id'] ?? '') ?></span><h2><?= h($review['reviewer_name'] ?? 'Khách hàng') ?></h2></div><span class="badge text-bg-<?= $active ? 'success' : 'secondary' ?>"><?= $active ? 'Đang hiển thị' : 'Đã ẩn' ?></span></div><div class="order-card-meta"><span class="stars"><?php for ($star = 1; $star <= 5; ++$star): ?><i class="fa-<?= $star <= (int) ($review['rating'] ?? 0) ? 'solid' : 'regular' ?> fa-star"></i><?php endfor; ?></span><span><?= h(isset($review['created_at']) ? date('d/m/Y H:i', strtotime((string) $review['created_at'])) : '—') ?></span><a href="/products/<?= rawurlencode((string) ($review['product_id'] ?? '')) ?>">Mở sản phẩm</a></div><p class="mb-3 text-break"><?= nl2br(h($review['content'] ?? '')) ?></p><?php if (is_array($adminResponse)): ?><div class="alert alert-light border"><strong>Phản hồi hiện tại · <?= h($adminResponse['staff_name'] ?? 'Nhân viên') ?></strong><p class="mb-0 mt-2 text-break"><?= nl2br(h($adminResponse['content'] ?? '')) ?></p></div><?php endif; ?><form class="mb-3" action="/admin/reviews/<?= rawurlencode((string) ($review['_id'] ?? '')) ?>/reply" method="post"><input type="hidden" name="csrf_token" value="<?= h(csrfToken()) ?>"><label class="form-label" for="reply-<?= h(substr(hash('sha256', (string) ($review['_id'] ?? '')), 0, 12)) ?>"><?= $adminResponse === null ? 'Phản hồi của cửa hàng' : 'Sửa phản hồi' ?></label><textarea class="form-control" id="reply-<?= h(substr(hash('sha256', (string) ($review['_id'] ?? '')), 0, 12)) ?>" name="content" maxlength="2000" rows="3" required><?= h($adminResponse['content'] ?? '') ?></textarea><button class="btn btn-sm btn-outline-primary mt-2" type="submit"><?= $adminResponse === null ? 'Gửi phản hồi' : 'Cập nhật phản hồi' ?></button></form><?php if ($manager): ?><form action="/admin/reviews/<?= rawurlencode((string) ($review['_id'] ?? '')) ?>/visibility" method="post"><input type="hidden" name="csrf_token" value="<?= h(csrfToken()) ?>"><input type="hidden" name="active" value="<?= $active ? '0' : '1' ?>"><button class="btn btn-sm btn-outline-<?= $active ? 'danger' : 'success' ?>" type="submit"><?= $active ? 'Ẩn đánh giá' : 'Khôi phục đánh giá' ?></button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section>
<?php $content = (string) ob_get_clean(); require dirname(__DIR__, 2) . '/layout.php';
